document.addEventListener('DOMContentLoaded',function(){const mainImage=document.getElementById('mainImage');const thumbnails=document.querySelectorAll('.thumbnail-container .img-thumbnail');window.changeImage=function(newSrc){if(mainImage){mainImage.src=newSrc}
thumbnails.forEach(thumb=>{if(thumb.getAttribute('onclick').includes(newSrc)){thumb.classList.add('active')}else{thumb.classList.remove('active')}})}
if(thumbnails.length>0&&mainImage){const firstThumbOnClick=thumbnails[0].getAttribute('onclick');if(firstThumbOnClick&&firstThumbOnClick.includes(mainImage.src)){thumbnails[0].classList.add('active')}
thumbnails.forEach(thumb=>{thumb.addEventListener('click',function(){thumbnails.forEach(t=>t.classList.remove('active'));this.classList.add('active')})})}
const colorSwatches=document.querySelectorAll('.color-swatch');const selectedColorSpan=document.getElementById('selectedColor');colorSwatches.forEach(swatch=>{swatch.addEventListener('click',function(){colorSwatches.forEach(s=>s.classList.remove('active'));this.classList.add('active');if(selectedColorSpan){selectedColorSpan.textContent=this.dataset.color||''}
console.log('Selected color:',this.dataset.color)})});const sizeOptions=document.querySelectorAll('.size-option');sizeOptions.forEach(option=>{option.addEventListener('click',function(){sizeOptions.forEach(o=>o.classList.remove('active'));this.classList.add('active');console.log('Selected size:',this.textContent)})});const quantityInput=document.getElementById('quantityInput');window.changeQuantity=function(amount){if(quantityInput){let currentValue=parseInt(quantityInput.value,10);let newValue=currentValue+amount;if(newValue<1){newValue=1}
quantityInput.value=newValue;console.log('Quantity:',newValue)}}
const addToCartButton=document.querySelector('.btn-add-to-cart');const wishlistButton=document.querySelector('.btn-wishlist');if(addToCartButton){addToCartButton.addEventListener('click',function(){console.log('Add to Cart clicked');alert('Added to cart! (Placeholder)')})}
if(wishlistButton){wishlistButton.addEventListener('click',function(){console.log('Add to Wishlist clicked');const icon=this.querySelector('i');if(icon){icon.classList.toggle('far');icon.classList.toggle('fas')}
alert('Added to wishlist! (Placeholder)')})}})